const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
const filters=document.querySelectorAll('[data-filter]'),cards=document.querySelectorAll('[data-category]');filters.forEach(button=>button.addEventListener('click',()=>{filters.forEach(b=>{const active=b===button;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active))});let count=0;cards.forEach(card=>{const show=button.dataset.filter==='All'||card.dataset.category===button.dataset.filter;card.hidden=!show;if(show){count++;card.classList.add('visible')}});document.querySelector('#filter-status').textContent=`Showing ${count} projects`;}));
if('IntersectionObserver' in window&&!reduced){const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('visible');observer.unobserve(entry.target)}}),{threshold:.08});document.querySelectorAll('.lab-card,.section-head,.service,.about-copy').forEach(el=>{el.classList.add('reveal','ready');observer.observe(el)})}
let ticking=false;function progress(){const max=document.documentElement.scrollHeight-innerHeight;document.querySelector('.reading-progress').style.width=(max>0?scrollY/max*100:0)+'%';ticking=false}addEventListener('scroll',()=>{if(!ticking){requestAnimationFrame(progress);ticking=true}},{passive:true});addEventListener('resize',progress);progress();
